function i(n){if(n==null||n==="")return"—";const e=Number(n);if(Number.isNaN(e))return"—";const t=Math.abs(e);return t>=1e8?`${(e/1e8).toFixed(1)}亿`:t>=1e4?`${(e/1e4).toFixed(t>=1e5?0:1)}万`:Number.isInteger(e)?String(e):e.toFixed(2)}function u(n){return n==null||n===""?"—":`¥${Number(n).toLocaleString("zh-CN")}`}function o(n){return n==null||n===""?"—":`${(Number(n)*100).toFixed(2)}%`}function s(n){if(!n)return"发布时间未知";const e=new Date(Number(n)*1e3);if(Number.isNaN(e.getTime()))return"发布时间未知";const t=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${t(e.getMonth()+1)}-${t(e.getDate())} ${t(e.getHours())}:${t(e.getMinutes())}`}const d=[{id:"",label:"全部地区"},{id:"cn",label:"大陆"},{id:"hk",label:"香港"},{id:"overseas",label:"海外 RED"}];export{d as R,u as m,i as n,o as p,s as w};
